---
import { getCollection, render } from 'astro:content';
import Layout from '../../layouts/Layout.astro';
export const prerender = false;
const books = await getCollection('books');
const book = books.find((b) => b.id === Astro.params.slug);
if (!book) return Astro.rewrite('/404');
const { Content } = await render(book);
const { title, author, year, rating, tags } = book.data;
---
<Layout title={`${title} | Bookshelf`}>
  <h1>{title}</h1>
  <p>by {author}</p>
  <p>Published in {year}</p>
  <p>Rating: {rating}/5</p>
  <ul aria-label="Tags">
    {tags.map((t) => <li><a href="/books">{t}</a></li>)}
  </ul>
  <div><Content /></div>
  <button type="button" id="fav" data-slug={book.id}>Add to favorites</button>
</Layout>
<script>
  const btn = document.getElementById('fav') as HTMLButtonElement;
  const slug = btn.dataset.slug!;
  const read = (): string[] => {
    try { return JSON.parse(localStorage.getItem('favorites') || '[]'); } catch { return []; }
  };
  const render = () => {
    btn.textContent = read().includes(slug) ? 'Remove from favorites' : 'Add to favorites';
  };
  btn.addEventListener('click', () => {
    const f = read();
    const next = f.includes(slug) ? f.filter((s) => s !== slug) : [...f, slug];
    localStorage.setItem('favorites', JSON.stringify(next));
    render();
  });
  render();
</script>
