---
import Layout from '../layouts/Layout.astro';
import { validateContact } from '../lib/validate';
export const prerender = false;
let values = { name: '', email: '', message: '' };
let errors: ReturnType<typeof validateContact> = {};
let success = '';
if (Astro.request.method === 'POST') {
  const f = await Astro.request.formData();
  const get = (k: string) => String(f.get(k) ?? '');
  values = { name: get('name'), email: get('email'), message: get('message') };
  errors = validateContact(values);
  if (Object.keys(errors).length === 0) success = `Thanks, ${values.name.trim()}! Your message has been sent.`;
}
---
<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <p id="success" role="status">{success}</p>
  <form method="post" action="/contact" novalidate hidden={!!success}>
    <div>
      <label for="name">Name</label>
      <input type="text" id="name" name="name" value={values.name} />
      <span class="error" data-for="name">{errors.name}</span>
    </div>
    <div>
      <label for="email">Email</label>
      <input type="email" id="email" name="email" value={values.email} />
      <span class="error" data-for="email">{errors.email}</span>
    </div>
    <div>
      <label for="message">Message</label>
      <textarea id="message" name="message">{values.message}</textarea>
      <span class="error" data-for="message">{errors.message}</span>
    </div>
    <button type="submit">Send</button>
  </form>
</Layout>
<script>
  import { validateContact } from '../lib/validate';
  const form = document.querySelector('form')!;
  const success = document.getElementById('success')!;
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const data = new FormData(form);
    const v = {
      name: String(data.get('name') ?? ''),
      email: String(data.get('email') ?? ''),
      message: String(data.get('message') ?? ''),
    };
    const errors = validateContact(v);
    for (const span of form.querySelectorAll<HTMLElement>('.error')) {
      span.textContent = errors[span.dataset.for as keyof typeof errors] ?? '';
    }
    if (Object.keys(errors).length) return;
    try { await fetch('/contact', { method: 'POST', body: data }); } catch {}
    success.textContent = `Thanks, ${v.name.trim()}! Your message has been sent.`;
    form.hidden = true;
  });
</script>
